// 参考: docs/store/I75-startup-layering-spec.md §6.2 — 生成窗口首帧配置需求

use std::fs;
use std::path::Path;

#[test]
fn export_window_requirements() {
    let labels: Vec<&str> = assistant_config::window_spec::WINDOW_SPECS
        .iter()
        .map(|spec| spec.label)
        .collect();

    let mut output = String::from(
        "// This file was generated by `npm run contract:gen` from\n\
         // `assistant_config::window_spec::WINDOW_SPECS`. Do not edit manually.\n\n\
         import type { ConfGroup } from \"@/settings/core/types/confRegistry\";\n\n",
    );
    output.push_str(&format!(
        "export const WINDOW_LABELS = [{}] as const;\n",
        labels
            .iter()
            .map(|label| format!("\"{}\"", label))
            .collect::<Vec<_>>()
            .join(", ")
    ));
    output.push_str("export type WindowLabel = (typeof WINDOW_LABELS)[number];\n");
    output.push_str(
        "export const WINDOW_CONF_REQUIREMENTS: Record<WindowLabel, readonly ConfGroup[]> = {\n",
    );
    for spec in assistant_config::window_spec::WINDOW_SPECS {
        output.push_str(&format!(
            "  {}: [{}],\n",
            spec.label,
            spec.confs
                .iter()
                .map(|conf| format!("\"{}\"", conf))
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    output.push_str("};\n");

    let out_path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../../src/settings/core/runtime/windowRequirements.generated.ts");
    if let Some(parent) = out_path.parent() {
        fs::create_dir_all(parent).expect("create contract directory");
    }
    fs::write(&out_path, output).expect("write window requirements");
}
